    "code": "function () {\n  const source = this.appSource;\n  // Detect the anti-pattern where the render function deletes ALL items from the\n  // existing-items tracking map (using `delete existingItems[id]` in a loop) BEFORE\n  // the reuse loop runs. This means the `existingItems[t.id]` lookup always returns\n  // undefined, and createElement('li') is ALWAYS called — the reuse branch is dead code.\n  //\n  // The buggy pattern:\n  //   for (var id in existingItems) {\n  //     existingItems[id].parentNode.removeChild(existingItems[id]);\n  //     delete existingItems[id];   // map emptied\n  //   }\n  //   for (var i = ...) {\n  //     var li = existingItems[t.id]; // always undefined\n  //     if (li) { ... reuse ... }     // dead code\n  //     else { createElement('li') ... } // always runs\n  //   }\n  //\n  // We detect: a loop that calls `delete` on existingItems entries, destroying the\n  // tracking map, combined with createElement('li') later on.\n  const hasDeleteFromMap = /delete\\s+existingItems\\[/.test(source);\n  const hasCreateLi = /createElement\\s*\\(\\s*['\"]li['\"]\\s*\\)/.test(source);\n  // Fail if the map is cleared by delete AND new li elements are created\n  // (meaning the reuse lookup can never succeed).\n  this.alwaysCreatesNewLis = hasDeleteFromMap && hasCreateLi;\n}",
